"""Evaluate requests against policy-filtered evidence records."""

import copy
import json


def _canonical_json(value):
    """Return a stable representation suitable for JSON-value comparison."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _superseded_ids(record):
    """Normalize the commonly used scalar or list supersedes field."""
    supersedes = record.get("supersedes", [])
    if supersedes is None:
        return []
    if isinstance(supersedes, (list, tuple, set)):
        return supersedes
    return [supersedes]


def evaluate(request, evidence, policy):
    """Return the policy-qualified assessment for one request."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    require_verified = policy.get("require_verified", False)
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if require_verified and record.get("verified") is not True:
            continue
        conditions = record.get("conditions", {})
        if any(
            name not in conditions
            or conditions[name] != request_conditions[name]
            for name in required
        ):
            continue
        eligible.append(record)

    # Supersession only has force when asserted by another eligible record.
    superseded = {
        source_id
        for record in eligible
        for source_id in _superseded_ids(record)
        if source_id != record.get("source")
    }
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record["source"] for record in eligible)
    canonical_values = {}
    for record in eligible:
        value = record.get("value")
        canonical_values.setdefault(_canonical_json(value), value)

    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = next(iter(canonical_values.values()))
    return {
        "status": "unsupported" if value is False else "supported",
        "value": copy.deepcopy(value),
        "sources": sources,
        "unknowns": [],
    }
